const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// 1. Verify shared webhook secret
const expectedSecret = $env.DOC_TRIAGE_WEBHOOK_SECRET || '';
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
if (!expectedSecret || providedSecret !== expectedSecret) {
  throw new Error('Unauthorized: invalid or missing X-Webhook-Secret header');
}

const rawSubject = String(body.subject || '').trim();
const rawBody = String(body.body || body.document_text || '').trim();
const maxChars = Number($env.AI_MAX_INPUT_CHARS || 12000);

// 2. Enforce strict input size spend cap before calling LLM
if (rawBody.length === 0) {
  throw new Error('Validation failed: document body is empty');
}
if (rawBody.length > maxChars) {
  throw new Error(`Spend guardrail triggered: input length (${rawBody.length} chars) exceeds limit (${maxChars} chars)`);
}

// 3. Redact sensitive PII & credentials pre-LLM
let redactionCount = 0;
const scrub = (text) => {
  let out = text;
  // Credit card numbers (13-19 digits with optional spaces or hyphens)
  out = out.replace(/\b(?:\d[ -]*?){13,19}\b/g, () => { redactionCount++; return '[REDACTED_CARD]'; });
  // SSN / formatted national IDs
  out = out.replace(/\b\d{3}-\d{2}-\d{4}\b/g, () => { redactionCount++; return '[REDACTED_ID]'; });
  // Bearer authorization tokens
  out = out.replace(/Bearer\s+[A-Za-z0-9._~+/=-]{12,}/gi, () => { redactionCount++; return 'Bearer [REDACTED_TOKEN]'; });
  return out;
};

const sanitizedSubject = scrub(rawSubject).slice(0, 300);
const sanitizedBody = scrub(rawBody);

return [{
  json: {
    ticket: {
      ticket_id: String(body.ticket_id || `DOC-${Date.now()}`),
      sender_name: String(body.sender_name || 'Unknown Sender').trim().slice(0, 120),
      sender_email: String(body.sender_email || '').trim().toLowerCase(),
      channel: String(body.channel || 'email').trim(),
      subject: sanitizedSubject,
      body: sanitizedBody,
      received_at: String(body.received_at || new Date().toISOString())
    },
    guardrails: {
      char_count: sanitizedBody.length,
      max_chars: maxChars,
      redaction_count: redactionCount
    }
  }
}];

const sanitized = $('PII Redaction & Budget Check').first().json;
const rawResponse = $input.first().json;
const content = rawResponse?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('AI triage returned empty content');
}

const triage = JSON.parse(content);
const threshold = Number($env.AI_CONFIDENCE_THRESHOLD ?? 0.80);
const resumeBase = $execution.resumeUrl;

return [{
  json: {
    ticket: sanitized.ticket,
    guardrails: sanitized.guardrails,
    triage,
    confidence_threshold: Number.isFinite(threshold) ? threshold : 0.80,
    below_confidence_threshold: triage.confidence < (Number.isFinite(threshold) ? threshold : 0.80),
    hitl_links: {
      approve: `${resumeBase}?decision=approved`,
      edit: `${resumeBase}?decision=edit`,
      reject: `${resumeBase}?decision=rejected`
    }
  }
}];

